# Extend C2 anchor to also catch plural 'are defined as/to be'
_c2_anchor_plural = re.compile(
    r"\bare\s+defined\s+(?:as|to\s+be)\s",
    flags=re.IGNORECASE,
)

# Also add a pattern for 'both ... are defined as <math block>'
# We reuse the same C2 two-phase logic with the plural anchor:
for anchor_m in _c2_anchor_plural.finditer(inline_text):
    start_search = max(0, anchor_m.start() - 80)
    prefix = inline_text[start_search:anchor_m.start()]
    dot_pos = prefix.rfind('.')
    if dot_pos >= 0:
        name_start = start_search + dot_pos + 1
    else:
        name_start = start_search
    name_text = inline_text[name_start:anchor_m.start()].strip()
    if not name_text or len(name_text) > 80:
        continue
    tail_m = _c2_tail.match(inline_text, anchor_m.end())
    if not tail_m:
        continue
    full_text = inline_text[name_start:tail_m.end()]
    _ns = name_start
    class _C2PluralMatch:
        def group(self, key):
            if key == 'full':
                return full_text
            if key == 'name':
                return name_text
            return None
        def start(self):
            return _ns
    add_inline_definition(_C2PluralMatch(), 'inline_defined_as')

